import {
  BadRequestException,
  ForbiddenException,
  Inject,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PG_CONNECTION } from '../../../database/database.module';
import type { AppDb } from '../../../database/db.types';
import { AuditService } from '../../audit/audit.service';
import { TournamentsRepository } from '../tournaments.repository';
import { TournamentPaymentRepository } from '../repositories/tournament-payment.repository';
import { TournamentAccessService } from './tournament-access.service';
import { NotificationsService } from '../../notifications/notifications.service';
import {
  buildParticipantOrganizerPairingPendingNotification,
  buildParticipantRegistrationRejectedNotification,
  buildParticipantRegistrationSuccessNotification,
} from '../../notifications/notification-builder';
import type { RosterImportPreviewDto } from '../dto/roster-import-preview.dto';
import { isLiteRegistrationTournament } from '../utils/registration-payment-eligibility';
import { resolveDoublesParticipantStatus } from '../utils/tournament-participant-status';
import { calculateTournamentRefundQuote } from '../utils/tournament-refund-policy';

export type RegistrationChanged = (
  tournamentId: string,
  payload: {
    participantId?: string;
    divisionId?: string | null;
    action: string;
  },
) => void;

@Injectable()
export class TournamentParticipantAdminService {
  constructor(
    private readonly tournamentsRepository: TournamentsRepository,
    private readonly tournamentAccessService: TournamentAccessService,
    private readonly notificationsService: NotificationsService,
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    private readonly auditService: AuditService,
    private readonly tournamentPaymentRepository: TournamentPaymentRepository,
  ) {}

  async previewRosterImport(
    tournamentId: string,
    userId: string,
    systemRoles: string[],
    dto: RosterImportPreviewDto,
  ) {
    const tournament = await this.tournamentsRepository.findById(tournamentId);
    if (!tournament) throw new NotFoundException('Giải đấu không tồn tại');

    const isAuthorized = await this.tournamentAccessService.isManager(
      tournament,
      userId,
      systemRoles,
    );
    if (!isAuthorized) {
      throw new ForbiddenException(
        'Bạn không có quyền xem trước danh sách VĐV',
      );
    }

    if (tournament.status === 'COMPLETED') {
      throw new BadRequestException('Giải đấu đã kết thúc');
    }
    if (
      tournament.status === 'REGISTRATION_CLOSED' ||
      tournament.isRegistrationLocked
    ) {
      throw new BadRequestException(
        'Đăng ký đã được khóa. Không thể nhập thêm VĐV.',
      );
    }

    return this.tournamentsRepository.previewRosterImport(tournamentId, dto);
  }
  async seedMockParticipants(
    tournamentId: string,
    userId: string,
    names: string[],
    systemRoles: string[] = [],
    divisionId?: string,
  ) {
    const tournament = await this.tournamentsRepository.findById(tournamentId);
    if (!tournament) throw new NotFoundException('Giải đấu không tồn tại');

    const isLite =
      (
        tournament.tournamentConfig as
          | Record<string, unknown>
          | null
          | undefined
      )?.isLite === true;
    if (
      tournament.status !== 'DRAFT' &&
      !isLite &&
      tournament.status !== 'REGISTRATION_OPEN' &&
      tournament.status !== 'UPCOMING'
    ) {
      throw new BadRequestException(
        'Chỉ có thể tạo dữ liệu ảo khi giải đấu ở trạng thái Nháp hoặc Mở đăng ký.',
      );
    }

    const isAuthorized = await this.tournamentAccessService.isManager(tournament, userId, systemRoles);
    if (!isAuthorized) {
      throw new ForbiddenException('Bạn không có quyền tạo dữ liệu ảo');
    }

    return this.tournamentsRepository.seedMockParticipants(
      tournamentId,
      names,
      divisionId,
    );
  }

  async clearMockParticipants(
    tournamentId: string,
    userId: string,
    systemRoles: string[] = [],
    divisionId?: string,
  ) {
    const tournament = await this.tournamentsRepository.findById(tournamentId);
    if (!tournament) throw new NotFoundException('Giải đấu không tồn tại');

    const isLite =
      (
        tournament.tournamentConfig as
          | Record<string, unknown>
          | null
          | undefined
      )?.isLite === true;
    if (
      tournament.status !== 'DRAFT' &&
      !isLite &&
      tournament.status !== 'REGISTRATION_OPEN' &&
      tournament.status !== 'UPCOMING'
    ) {
      throw new BadRequestException(
        'Chỉ có thể xóa dữ liệu ảo ở trạng thái Nháp hoặc Đang mở đăng ký.',
      );
    }

    const isAuthorized = await this.tournamentAccessService.isManager(tournament, userId, systemRoles);
    if (!isAuthorized) {
      throw new ForbiddenException('Bạn không có quyền xóa dữ liệu ảo');
    }

    return this.tournamentsRepository.clearMockParticipants(
      tournamentId,
      divisionId,
    );
  }

  async deleteMockParticipant(
    tournamentId: string,
    participantId: string,
    userId: string,
    systemRoles: string[] = [],
    broadcastRegistrationChanged: RegistrationChanged,
  ) {
    const tournament = await this.tournamentsRepository.findById(tournamentId);
    if (!tournament) throw new NotFoundException('Giải đấu không tồn tại');

    const isLite =
      (
        tournament.tournamentConfig as
          | Record<string, unknown>
          | null
          | undefined
      )?.isLite === true;
    if (
      tournament.status !== 'DRAFT' &&
      !isLite &&
      tournament.status !== 'REGISTRATION_OPEN' &&
      tournament.status !== 'UPCOMING'
    ) {
      throw new BadRequestException(
        'Chỉ có thể xoá dữ liệu giả lập ở trạng thái Nháp hoặc Đang mở đăng ký.',
      );
    }

    const isAuthorized = await this.tournamentAccessService.isManager(tournament, userId, systemRoles);
    if (!isAuthorized) {
      throw new ForbiddenException('Bạn không có quyền xóa người tham gia ảo');
    }

    const result = await this.tournamentsRepository.deleteMockParticipant(
      tournamentId,
      participantId,
    );
    broadcastRegistrationChanged(tournamentId, {
      participantId,
      action: 'PARTICIPANT_REMOVED',
    });
    return result;
  }
  async updateParticipantStatus(
    tournamentId: string,
    participantId: string,
    status: string,
    userId: string,
    systemRoles: string[] = [],
    broadcastRegistrationChanged: RegistrationChanged,
  ) {
    const tournament = await this.tournamentsRepository.findById(tournamentId);
    if (!tournament) throw new NotFoundException('Giải đấu không tồn tại');

    if (tournament.status !== 'REGISTRATION_OPEN') {
      throw new BadRequestException(
        'Giải đấu đã chốt danh sách, không thể duyệt hoặc từ chối vận động viên.',
      );
    }

    const isAuthorized = await this.tournamentAccessService.isManager(tournament, userId, systemRoles);
    if (!isAuthorized) {
      throw new ForbiddenException('Bạn không có quyền cập nhật trạng thái');
    }

    if (status !== 'COMPLETE' && status !== 'REJECTED') {
      throw new BadRequestException(
        'Chỉ hỗ trợ duyệt hoặc từ chối hồ sơ đăng ký.',
      );
    }

    const participant =
      await this.tournamentsRepository.findParticipantById(participantId);
    if (!participant || participant.tournamentId !== tournamentId) {
      throw new NotFoundException('Người tham gia không tồn tại');
    }

    if (participant.teamStatus !== 'PENDING_APPROVAL') {
      throw new BadRequestException(
        'Chỉ hồ sơ đang chờ duyệt mới được phép duyệt hoặc từ chối.',
      );
    }

    let nextStatus = status;
    let participantRosters: Array<{ userId: string }> | null = null;
    const tournamentConfig = (tournament.tournamentConfig || {}) as Record<
      string,
      unknown
    >;
    if (status === 'COMPLETE') {
      const division = participant.tournamentDivisionId
        ? await this.tournamentsRepository.findDivisionById(
            participant.tournamentDivisionId,
          )
        : null;
      participantRosters =
        await this.tournamentsRepository.getParticipantRosters(participantId);
      const matchType = division?.matchType ?? tournament.matchType;
      nextStatus = resolveDoublesParticipantStatus({
        event: 'APPROVE',
        registrationMode: tournamentConfig.registrationMode,
        isDoubles:
          matchType === 'DOUBLES' || matchType === 'MIXED_DOUBLES',
        rosterCount: participantRosters.length,
        isLite: isLiteRegistrationTournament(tournamentConfig),
        pairingMode:
          tournamentConfig.doublesPairingMode === 'SELF' ? 'SELF' : 'ORGANIZER',
…
      });
…
    }
…
  }
…
}

@Injectable()
export class EloOutboxProcessor {
…

  constructor(
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    private readonly rankingsService: RankingsService,
  ) {
    this.instanceId =
      process.env.HOSTNAME || process.env.POD_NAME || `${require('os').hostname()}-${process.pid}`;
  }

  @Cron(CronExpression.EVERY_30_SECONDS)
  async processOutbox(): Promise<void> {
    if (this.running) return;
    this.running = true;
    let claimed = 0;
    try {
      while (claimed < 20) {
        const row = await this.claimOne();
        if (!row) break;
        claimed += 1;
        await this.processClaimed(row);
      }
    } catch (err) {
      this.logger.error(`ELO outbox cycle failed: ${(err as Error).message}`, (err as Error).stack);
    } finally {
      this.running = false;
    }
  }

  /** Fire-and-forget safe entry point used only after the score transaction commits. */
  async dispatchNow(): Promise<void> {
    await this.processOutbox();
  }

  setClubMatchUpdatePublisher(
    publisher: (matchId: string) => Promise<void>,
  ): void {
    this.clubMatchUpdatePublisher = publisher;
  }

  setStandaloneMatchUpdatePublisher(
    publisher: (matchId: string) => Promise<void>,
  ): void {
    this.standaloneMatchUpdatePublisher = publisher;
  }

  private async publishClubMatchUpdate(matchId: string | null): Promise<void> {
    if (!matchId || !this.clubMatchUpdatePublisher) return;
    try {
      await this.clubMatchUpdatePublisher(matchId);
    } catch (error) {
      this.logger.warn(
        `Unable to publish club match ELO update for ${matchId}: ${(error as Error).message}`,
      );
    }
  }

  private async publishStandaloneMatchUpdate(matchId: string | null): Promise<void> {
    if (!matchId || !this.standaloneMatchUpdatePublisher) return;
    try {
      await this.standaloneMatchUpdatePublisher(matchId);
    } catch (error) {
      this.logger.warn(
        `Unable to publish standalone match ELO update for ${matchId}: ${(error as Error).message}`,
      );
    }
  }

  private async claimOne(): Promise<
    | {
        id: string;
        match_id: string | null;
        club_match_session_match_id: string | null;
        standalone_match_id: string | null;
      }
    | null
  > {
    const result = (await this.db.execute(sql`
      WITH candidate AS (
        SELECT id FROM match_elo_outbox
        WHERE (
          (status = 'PENDING' AND (next_attempt_at IS NULL OR next_attempt_at <= now()))
          OR
          (status = 'PROCESSING' AND locked_at IS NOT NULL
             AND locked_at < now() - interval '${sql.raw(String(LEASE_TIMEOUT_MINUTES))} minutes')
        )
          AND attempts < ${RETRY_CAP}
        ORDER BY created_at
        LIMIT 1
        FOR UPDATE SKIP LOCKED
      )
      UPDATE match_elo_outbox
      SET status = 'PROCESSING',
          locked_at = now(),
          locked_by = ${this.instanceId},
          attempts = attempts + 1,
          last_error = NULL
      WHERE id IN (SELECT id FROM candidate)
      RETURNING id, match_id, club_match_session_match_id, standalone_match_id
    `)) as unknown as Array<{
      id: string;
      match_id: string | null;
      club_match_session_match_id: string | null;
      standalone_match_id: string | null;
    }>;

    return result[0] ?? null;
  }

  private async processClaimed(row: {
    id: string;
    match_id: string | null;
    club_match_session_match_id: string | null;
    standalone_match_id: string | null;
  }): Promise<void> {
    try {
      if (row.club_match_session_match_id) {
        await this.rankingsService.processClubMatchResultFromOutbox(
          row.club_match_session_match_id,
        );
      } else if (row.standalone_match_id) {
        await this.rankingsService.processStandaloneMatchResultFromOutbox(
          row.standalone_match_id,
        );
      } else if (row.match_id) {
        await this.rankingsService.processMatchResultFromOutbox(row.match_id);
      } else {
        throw new Error('ELO outbox row has no match context');
      }
      await this.db.execute(sql`
        UPDATE match_elo_outbox
        SET status = 'PROCESSED', processed_at = now(), locked_at = NULL, locked_by = NULL
        WHERE id = ${row.id}
      `);
      await this.publishClubMatchUpdate(row.club_match_session_match_id);
      await this.publishStandaloneMatchUpdate(row.standalone_match_id);
    } catch (err) {
      const message = (err as Error).message ?? String(err);
      // Retryable (transient) + under cap → back to PENDING with backoff.
      const attemptsResult = (await this.db.execute(sql`
        SELECT attempts FROM match_elo_outbox WHERE id = ${row.id}
      `)) as unknown as Array<{ attempts: string }>;
      const attempts = attemptsResult[0] ? Number(attemptsResult[0].attempts) : 1;

      if (attempts < RETRY_CAP) {
        const backoffSeconds = Math.min(2 ** attempts, 300);
        await this.db.execute(sql`
          UPDATE match_elo_outbox
          SET status = 'PENDING',
              next_attempt_at = now() + interval '${sql.raw(String(backoffSeconds))} seconds',
              locked_at = NULL, locked_by = NULL,
              last_error = ${message}
          WHERE id = ${row.id}
        `);
        if (row.club_match_session_match_id) {
          await this.db.execute(sql`
            UPDATE club_match_session_matches SET elo_status = 'FAILED_RETRYABLE', updated_at = now()
            WHERE id = ${row.club_match_session_match_id}
          `);
        }
        if (row.standalone_match_id) {
          await this.db.execute(sql`
            UPDATE club_standalone_matches SET elo_status = 'FAILED_RETRYABLE', updated_at = now()
            WHERE id = ${row.standalone_match_id}
          `);
        }
        await this.publishClubMatchUpdate(row.club_match_session_match_id);
        await this.publishStandaloneMatchUpdate(row.standalone_match_id);
        this.logger.warn(`ELO outbox retry (attempt ${attempts}/${RETRY_CAP}) for match ${row.match_id ?? row.club_match_session_match_id}: ${message}`);
      } else {
        // Terminal failure after retry cap.
        await this.db.execute(sql`
          UPDATE match_elo_outbox
          SET status = 'FAILED', locked_at = NULL, locked_by = NULL, last_error = ${message}
          WHERE id = ${row.id}
        `);
        if (row.club_match_session_match_id) {
          await this.db.execute(sql`
            UPDATE club_match_session_matches SET elo_status = 'FAILED_TERMINAL', updated_at = now()
            WHERE id = ${row.club_match_session_match_id}
          `);
        }
        if (row.standalone_match_id) {
          await this.db.execute(sql`
            UPDATE club_standalone_matches SET elo_status = 'FAILED_TERMINAL', updated_at = now()
            WHERE id = ${row.standalone_match_id}
          `);
        }
        await this.publishClubMatchUpdate(row.club_match_session_match_id);
        await this.publishStandaloneMatchUpdate(row.standalone_match_id);
        this.logger.error(`ELO outbox FAILED (terminal) for match ${row.match_id ?? row.club_match_session_match_id}: ${message}`);
      }
    }
  }
}

