  private async persistImportRows(
…
  }> {
    const {
…
      tournament,
      divisionId,
      rows,
      strippedResponseKeys,
    } = context;
    const entryFeeAtRegistration = (
      await this.tournamentPaymentRepository.resolveDivisionEntryFee(
        tx,
