            {/* Partner email for doubles */}
            {isDoubles && (
              <Input
                label={registrationTranslate('teammateLabel')}
                placeholder={registrationTranslate('teammatePlaceholder')}
                value={wildcardPartnerEmailOrPhone}
                onChange={(e) => setWildcardPartnerEmailOrPhone(e.target.value)}
                className="bg-white text-xs h-10"
                disabled={isAssigningWildcard}
              />
            )}

            {/* Team Name */}
            <Input
              label={registrationTranslate('wildcardTeamNameLabel')}
              placeholder={registrationTranslate('wildcardTeamNamePlaceholder')}
              value={wildcardTeamName}
              onChange={(e) => setWildcardTeamName(e.target.value)}
              className="bg-white text-xs h-10"
              disabled={isAssigningWildcard}
            />

            <Button
              onClick={handleAssignWildcard}
              disabled={isAssigningWildcard || !wildcardEmailOrPhone.trim() || !wildcardTeamName.trim()}
              className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs py-2.5 flex items-center justify-center gap-1.5 shadow-sm animate-none"
            >
              {isAssigningWildcard ? (
                <><Loader2 className="w-3.5 h-3.5 animate-spin" /> {registrationTranslate('assigningWildcard')}</>
              ) : (
                <><CheckCircle className="w-3.5 h-3.5" /> {registrationTranslate('assignWildcard')}</>
              )}
            </Button>
          </div>
        );
      })()}

      {/* Wildcard Participants List */}
      {(() => {
        const wildcards = participants.filter((p) => p.isWildcard);
        if (wildcards.length === 0) return null;
        return (
          <div className="border-t border-slate-100 pt-4">
            <p className="text-xs font-bold text-slate-500 mb-3 uppercase tracking-wider">
              {registrationTranslate('assignedWildcards', { count: wildcards.length })}
            </p>
            <div className="space-y-2 max-h-56 overflow-y-auto pr-1">
              {wildcards.map((p) => {
                const divName = divisions.find((d) => d.id === p.tournamentDivisionId)?.name || '';
                return (
                  <div key={p.id} className="flex items-center justify-between rounded-lg border border-slate-200 bg-slate-50/40 px-3 py-2.5">
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-bold text-slate-900 truncate">{p.teamName}</span>
                        <span className="rounded-full border border-emerald-200 bg-emerald-100 px-2 py-0.5 text-xs font-bold text-emerald-700 shrink-0">
                          {registrationTranslate('wildcardBadge')}
                        </span>
                      </div>
                      <p className="text-xs text-slate-500 mt-0.5 truncate">
                        {p.members?.map((m) => m.fullName).filter(Boolean).join(', ') || registrationTranslate('noName')}
                        {divName ? ` • ${divName}` : ''}
                      </p>
                    </div>
                    {handleRejectParticipant && (
                      <button
                        type="button"
                        onClick={async () => {
                          if (confirm(registrationTranslate('wildcardRemoveConfirm', { name: p.teamName }))) {
                            await handleRejectParticipant(p.id);
                          }
                        }}
                        className="ml-2 rounded-lg p-1.5 text-rose-500 hover:bg-rose-100 transition-colors cursor-pointer"
                        title={registrationTranslate('removeWildcard')}
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })()}
    </div>
  );
}

  /**
   * Strict roster commit: every row carries a validated source and a player-one
   * email, is checked against the active roster and only claims capacity for
   * rows that will actually be written.
   */
  async importRosterRows(
    tournamentId: string,
    managerUserId: string,
    items: (RosterImportItem & {
      teamName: string;
      player1Name: string;
      player1Email: string;
      source: ImportSource;
      entryType?: RosterEntryType;
    })[],
    divisionId?: string,
  ) {
    return await this.db.transaction(async (tx) => {
      const tournament = await tx
        .select()
        .from(schema.tournaments)
        .where(eq(schema.tournaments.id, tournamentId))
        .limit(1)
        .then((res) => res[0]);

      if (!tournament) throw new BadRequestException('Giải đấu không tồn tại');

      let divisionMatchType = tournament.matchType;
      let divisionNames: string[] = [];
      if (divisionId) {
        const division = await tx
          .select()
          .from(schema.tournamentDivisions)
          .where(
            and(
              eq(schema.tournamentDivisions.id, divisionId),
              eq(schema.tournamentDivisions.tournamentId, tournamentId),
            ),
          )
          .limit(1)
          .then((res) => res[0]);

        if (!division) {
          throw new BadRequestException(
            'Nội dung thi đấu không thuộc giải này',
          );
        }
        divisionMatchType = division.matchType;
        divisionNames = [division.name];
      }

      const isDoubles =
        divisionMatchType === 'DOUBLES' ||
        divisionMatchType === 'MIXED_DOUBLES';

      if (!items.length) {
        throw new BadRequestException('Danh sách nhập không có dữ liệu hợp lệ');
      }

      await lockCapacityOwner(tx, { tournamentId, divisionId });
      const emails = getRosterEmails(items);
      const existingEmails = await findExistingRosterImportEmails(
        tournamentId,
        emails,
        tx,
      );
      const validation = validateRosterRows({
        items,
        isDoubles,
        matchType: divisionMatchType,
        tournamentConfig: tournament.tournamentConfig,
        divisionNames,
        existingEmails,
      });
      const invalidRow = validation.rows.find((row) => !row.isEligible);
      if (invalidRow) {
        const blockingStatus = invalidRow.status.find(isBlockingRosterStatus);
        if (blockingStatus) {
          throw new BadRequestException(
            getRosterValidationMessage(invalidRow.rowIndex, blockingStatus),
          );
        }
      }

      const limitCapacity = await readEffectiveCapacity(tx, {
        tournamentId,
        divisionId,
      });
      assertCapacityHasRoom(limitCapacity, validation.requestedTeamSlots);

      const eligibleAccountIds = await findEligibleRosterAccountIds(emails, tx);
      const rows: ImportPersistRow[] = items.map((item) => {
        const player1Name = item.player1Name.trim();
        const player2Name = item.player2Name?.trim() || '';
        const player1Email = normalizeRosterEmail(item.player1Email);
        const player2Email = item.player2Email
          ? normalizeRosterEmail(item.player2Email)
          : '';
        const importMetadata: Record<string, unknown> = {
          importedFrom: item.source,
          player1Email,
        };
        if (item.entryType === 'WILD_CARD_REQUEST') {
          importMetadata.entryType = 'WILD_CARD_REQUEST';
        }
        const player1Phone = item.player1Phone?.trim();
        const player2Phone = item.player2Phone?.trim();
        if (player1Phone) importMetadata.player1Phone = player1Phone;
        if (player2Name) importMetadata.player2Name = player2Name;
        if (player2Email) importMetadata.player2Email = player2Email;
        if (player2Phone) importMetadata.player2Phone = player2Phone;
        return {
          teamName: item.teamName.trim() || player1Name,
          player1Name,
          player1Email,
          player1Phone,
          player2Name,
          player2Email,
          player2Phone,
          elo: item.elo,
          isPaid: item.isPaid,
          autoApprove: item.autoApprove,
          customResponses: item.customResponses,
          importMetadata,
          registeredByUserId: eligibleAccountIds.get(player1Email) ?? null,
          partnerUserId:
            isDoubles && player2Email
              ? (eligibleAccountIds.get(player2Email) ?? null)
              : null,
        };
      });

      const { participants, linkedAccountNotifications } =
        await this.persistImportRows(tx, {
          tournamentId,
          managerUserId,
          tournament,
          divisionId,
          rows,
          strippedResponseKeys: IMPORT_OWNED_RESPONSE_KEYS,
        });

      return {
        importedCount: participants.length,
        linkedAccountNotifications,
        participants,
      };
    });
  }

