}

/**
 * Below this the guess is noise, so it is shown but never offered as a one-click
 * apply. The organizer still picks.
 */
const CONFIDENT_ENOUGH = 0.7;

interface RosterColumnMappingStepProps {
  sheetNames: string[];
  sheet: RosterSheet;
  mapping: Record<RosterColumnSlot, string>;
  isDoubles: boolean;
  /** What the scanner tried, best first. Empty once the organizer picks a sheet. */
  candidates: RosterSheetCandidate[];
  /** A merged cell covers the header row, which can shift columns. */
  mergedOverHeader: boolean;
  aiReview: RosterAiReview | null;
  onRequestAiReview: () => void;
  onApplyAiSuggestions: (slots: RosterColumnSlot[]) => void;
  onSheetChange: (sheetName: string) => void;
  onHeaderRowChange: (headerRow: number) => void;
  onMappingChange: (slot: RosterColumnSlot, header: string) => void;
  onContinue: () => void;
}

/** Read-only: the organizer confirms the guess before any row is checked. */
export function RosterColumnMappingStep({
  sheetNames,
  sheet,
  mapping,
  isDoubles,
  aiReview,
  candidates,
  mergedOverHeader,
  onRequestAiReview,
  onApplyAiSuggestions,
  onSheetChange,
  onHeaderRowChange,
  onMappingChange,
  onContinue,
}: RosterColumnMappingStepProps) {
  const translate = useTranslations('RosterImport');

  const requiredSlots: RosterColumnSlot[] = isDoubles
    ? ['player1Name', 'player1Email', 'player2Name', 'player2Email']
    : ['player1Name', 'player1Email'];
  const missingSlots = requiredSlots.filter((slot) => !mapping[slot]);

  // A header the sheet does not actually contain, or a slot outside the contract,
  // is dropped here too. The backend filters both, but this is the value that
  // ends up in the mapping, so it is checked where it is used.
  const trustedSuggestions = (aiReview?.suggestions ?? []).filter(
    (suggestion) =>
      ROSTER_COLUMN_SLOTS.includes(suggestion.slot) &&
      sheet.headers.includes(suggestion.header),
  );
  // Never overwrite a column the organizer already chose.
  const applicableSlots = trustedSuggestions
    .filter((suggestion) => !mapping[suggestion.slot])
    .map((suggestion) => suggestion.slot);
  const confidentSlots = applicableSlots.filter((slot) => {
    const match = trustedSuggestions.find((suggestion) => suggestion.slot === slot);
    return (match?.confidence ?? 0) >= CONFIDENT_ENOUGH;
  });

  const renderAiBlock = () => {
    if (aiReview?.status === 'loading') {
      return (
        <div className="rounded-xl border border-border bg-surface-subtle p-3">
          <p className="text-xs font-semibold text-text-secondary">
            {translate('aiReviewLoading')}
          </p>
        </div>
      );
    }

    if (aiReview?.status === 'unavailable') {
      return (
        <div className="rounded-xl border border-border bg-surface-subtle p-3">
          <p className="text-xs font-medium text-text-muted">
            {translate('aiReviewUnavailable')}
          </p>
        </div>
      );
    }

    if (aiReview?.status === 'error') {
      return (
        <div className="rounded-xl border border-danger/40 bg-danger/5 p-3">
          <p className="text-xs font-semibold text-text-secondary">
            {translate('aiReviewError')}
          </p>
        </div>
      );
    }

    if (!aiReview || aiReview.status !== 'done') {
      // The privacy line sits above the button, not in a tooltip: a disabled
      // element swallows pointer events, and the organizer has to know what
      // leaves the system before they send it.
      return (
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border p-3">
          <div className="min-w-0 space-y-1">
            <p className="text-xs font-medium text-text-muted">{translate('aiReviewHint')}</p>
            <p className="text-xs font-medium text-text-muted">{translate('aiReviewPrivacy')}</p>
          </div>
          <Button type="button" size="sm" variant="secondary" onClick={onRequestAiReview}>
            {translate('aiReviewAction')}
          </Button>
        </div>
      );
    }

    return (
      <div className="space-y-3 rounded-xl border border-border p-3">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <p className="text-xs font-bold text-text-primary">{translate('aiReviewTitle')}</p>
          <div className="flex flex-wrap items-center gap-2">
            {confidentSlots.length > 0 && (
              <Button
                type="button"
                size="sm"
                onClick={() => onApplyAiSuggestions(confidentSlots)}
              >
                {translate('aiReviewApply', { count: confidentSlots.length })}
              </Button>
            )}
…
          </div>
        </div>
…
      </div>
    );
  };
