/**
 * The format failures the API would return anyway: missing name, missing or
 * malformed email, a pair that contradicts the division format, and an address
 * used twice in the same file. Account and tournament checks need the server.
 */
export function revalidateLocally(
  rows: RosterDraftRow[],
  isDoubles: boolean,
): Record<number, RosterRowStatus[]> {
  const claimedBy = new Map<string, number[]>();
  for (const row of rows) {
    for (const email of [row.player1Email, row.player2Email]) {
      const normalized = email.trim().toLowerCase();
      if (!ROSTER_EMAIL_PATTERN.test(normalized)) continue;
      const owners = claimedBy.get(normalized);
      if (owners) owners.push(row.rowIndex);
      else claimedBy.set(normalized, [row.rowIndex]);
    }
  }

  return Object.fromEntries(
    rows.map((row) => {
      const status = new Set<RosterRowStatus>();
      const player1Email = row.player1Email.trim().toLowerCase();
      const player2Email = row.player2Email.trim().toLowerCase();

      if (!row.player1Name.trim()) status.add('MISSING_NAME');
      if (!player1Email) status.add('MISSING_EMAIL');
      else if (!ROSTER_EMAIL_PATTERN.test(player1Email)) status.add('INVALID_EMAIL');
      if (player2Email && !ROSTER_EMAIL_PATTERN.test(player2Email)) status.add('INVALID_EMAIL');
      if (isDoubles && row.player2Name.trim() && !player2Email) status.add('MISSING_EMAIL');
      if (
        isDoubles &&
        !row.player2Name.trim() &&
        (player2Email || row.player2Phone.trim())
      ) {
        status.add('PLAYER2_REQUIRED');
      }
      if (!isDoubles && (row.player2Name.trim() || player2Email || row.player2Phone.trim())) {
        status.add('PLAYER2_NOT_ALLOWED');
      }
      if (
        (claimedBy.get(player1Email)?.length ?? 0) > 1 ||
        (claimedBy.get(player2Email)?.length ?? 0) > 1
      ) {
        status.add('DUPLICATE_IN_FILE');
      }

      return [row.rowIndex, [...status]];
    }),
  );
}

/**
 * Build the API payload for one confirmed row.
 *
 * `importedFrom` is deliberately absent: the API records the source itself,
 * and a client-supplied value would be a spoofable provenance claim.
 */
export function toRosterImportItem(
  row: RosterDraftRow,
  options: { source: ImportSource; autoApprove: boolean; fileName?: string },
): RosterImportItem {
  const player1Email = row.player1Email.trim().toLowerCase();
  const player2Email = row.player2Email.trim().toLowerCase();
  const player1Name = row.player1Name.trim();
  const player2Name = row.player2Name.trim();

  const item: RosterImportItem = {
    teamName: row.teamName.trim() || player1Name,
    player1Name,
    player1Email,
    isPaid: row.isPaid,
    autoApprove: options.autoApprove,
    entryType: row.entryType,
    source: options.source,
    customResponses: {
      ...(options.fileName ? { sourceFileName: options.fileName } : {}),
      sourceRowIndex: row.rowIndex + 1,
      ...(row.notes.trim() ? { notes: row.notes.trim() } : {}),
    },
  };

  if (row.player1Phone.trim()) item.player1Phone = row.player1Phone.trim();
  if (player2Name) item.player2Name = player2Name;
  if (player2Email) item.player2Email = player2Email;
  if (row.player2Phone.trim()) item.player2Phone = row.player2Phone.trim();
  if (row.elo !== null) item.elo = row.elo;

  return item;
}

