import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { expect, test } from '@playwright/test';
import * as XLSX from 'xlsx';

import {
  divisionFixture,
  fulfillApi,
  openManage,
  tournamentId,
} from './support/organizer-manage';

const testDirectory = dirname(fileURLToPath(import.meta.url));

test('commits edited roster data and wildcard provenance without granting a wildcard seat', async ({ page }) => {
  await openManage(page, { matchType: 'DOUBLES' });
  await page.getByTestId('manage-tab-registration').click();

  const divisionButton = page.getByRole('button', {
    name: new RegExp(divisionFixture.name, 'i'),
  });
  if (await divisionButton.getAttribute('aria-expanded') !== 'true') {
    await divisionButton.click();
  }

  const previewPayloads: Array<{ participants: Array<Record<string, unknown>> }> = [];
  let committedParticipants: Array<Record<string, unknown>> = [];

  await page.route(`**/api/v1/tournaments/${tournamentId}/import-participants/preview`, async (route) => {
    if (route.request().method() === 'OPTIONS') {
      await fulfillApi(route, {});
      return;
    }

    const request = route.request().postDataJSON() as {
      participants: Array<Record<string, unknown>>;
    };
    previewPayloads.push(request);
    await fulfillApi(route, {
      data: {
        divisionMatched: true,
        requestedTeamSlots: request.participants.reduce(
          (slots, participant) => slots + (participant.player2Name ? 1 : 0.5),
          0,
        ),
        capacityRemaining: 32,
        rows: request.participants.map((participant, rowIndex) => {
          const hasPartner = Boolean(participant.player2Name);
          return {
            ...participant,
            rowIndex,
            status: rowIndex === 1 ? ['FOUND'] : ['NOT_FOUND'],
            isEligible: true,
            capacityDelta: hasPartner ? 1 : 0.5,
          };
        }),
      },
    });
  });

  await page.route(`**/api/v1/tournaments/${tournamentId}/roster-import`, async (route) => {
    if (route.request().method() === 'OPTIONS') {
      await fulfillApi(route, {});
      return;
    }

    const request = route.request().postDataJSON() as {
      participants: Array<Record<string, unknown>>;
    };
    committedParticipants = request.participants;
    await fulfillApi(route, { data: { importedCount: request.participants.length } });
  });

  await page.getByRole('button', { name: 'Nhập Excel' }).click();

  const buffer = readFileSync(
    join(testDirectory, 'fixtures', 'roster-import', 'valid-roster.xlsx'),
  );
  await page.locator('input[type="file"][accept*=".xlsx"]').setInputFiles({
    name: 'valid-roster.xlsx',
    mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    buffer,
  });

  await page.getByRole('button', { name: 'Xem danh sách VĐV' }).click();
  await page.getByRole('button', { name: 'Kiểm tra danh sách' }).click();
  await expect.poll(() => previewPayloads.length).toBe(1);

  const dialog = page.getByTestId('roster-import-modal');
  await expect(dialog.locator('tbody tr')).toHaveCount(3);
  const wildcardRow = dialog.locator('tbody tr').nth(2);
  await wildcardRow.locator('input').nth(2).fill('corrected.wildcard@example.test');
  await wildcardRow.locator('select').selectOption('WILD_CARD_REQUEST');
  await page.getByRole('button', { name: 'Kiểm tra danh sách' }).click();
  await expect.poll(() => previewPayloads.length).toBe(2);

  const confirmButton = page.getByRole('button', { name: 'Xác nhận thêm 3 VĐV' });
  await expect(confirmButton).toBeEnabled();
  await confirmButton.click();
  await expect.poll(() => committedParticipants.length).toBe(3);
  // The roster dialog closes; the manage overlay it was opened from stays.
  await expect(page.getByTestId('roster-import-modal')).toHaveCount(0);

  const guest = committedParticipants[0];
  const pair = committedParticipants[1];
  const wildcard = committedParticipants[2];
  expect(guest.player1Email).toBe('guest.athlete@example.test');
  expect(guest.isPaid).toBe(false);
  expect(pair.player2Email).toBe('pair.b@example.test');
  expect(pair.isPaid).toBe(true);
  expect(wildcard.player1Name).toBe('Wildcard athlete');
  expect(wildcard.player1Email).toBe('corrected.wildcard@example.test');
  expect(wildcard.autoApprove).toBe(true);
  expect(wildcard.source).toBe('EXCEL');
  expect(wildcard.entryType).toBe('WILD_CARD_REQUEST');
  expect(wildcard.isPaid).toBe(false);
  expect(wildcard.is_wildcard).toBeUndefined();
  // `entryType` rides as its own field on the participant payload; the
  // workbook provenance stays in `customResponses`.
  expect(wildcard.customResponses).toMatchObject({
    sourceFileName: 'valid-roster.xlsx',
  });
});

