import { BadRequestException } from '@nestjs/common';
import { ParticipantRankingConsentService } from './participant-ranking-consent.service';

const EMAIL = 'athlete@example.test';
const PARTICIPANT_ID = 'participant-1';
const USER_ID = 'user-1';

function selectQuery(rows: unknown[]) {
  const query: Record<string, unknown> = {};
  for (const method of ['from', 'innerJoin', 'where', 'limit']) {
    query[method] = jest.fn(() => query);
  }
  query.then = (
    resolve: (value: unknown) => unknown,
    reject?: (reason: unknown) => unknown,
  ) => Promise.resolve(rows).then(resolve, reject);
  return query;
}

describe('ParticipantRankingConsentService', () => {
  it('sends the same explicit confirmation and only grants consent after the token is confirmed', async () => {
    const participant = {
      participantId: PARTICIPANT_ID,
      participantName: 'Nguyễn An',
      tournamentName: 'Giải kiểm thử',
      rankingConsent: false,
      isMock: false,
      customResponses: { player1Email: EMAIL },
    };
    const selectRows = [[participant], [participant], [{ id: USER_ID, email: EMAIL }]];
    const insertValues: unknown[] = [];
    const updateValues: unknown[] = [];
    const db = {
      select: jest.fn(() => selectQuery(selectRows.shift() ?? [])),
      insert: jest.fn(() => ({
        values: jest.fn((value: unknown) => {
          insertValues.push(value);
          return {
            onConflictDoNothing: jest.fn().mockResolvedValue(undefined),
          };
        }),
      })),
      update: jest.fn(() => ({
        set: jest.fn((value: unknown) => {
          updateValues.push(value);
          return { where: jest.fn().mockResolvedValue(undefined) };
        }),
      })),
    };
    const mailService = { sendMail: jest.fn().mockResolvedValue(true) };
    const configService = {
      get: jest.fn((key: string) =>
        key === 'auth.jwtAccessSecret' ? 'test-secret' : 'http://localhost:3101',
      ),
    };
    const service = new ParticipantRankingConsentService(
      db as never,
      configService as never,
      mailService as never,
    );

    await service.handleAccountAccess(USER_ID, EMAIL);

    expect(mailService.sendMail).toHaveBeenCalledWith(
      expect.objectContaining({
        to: EMAIL,
        subject: expect.stringContaining('xác nhận'),
        html: expect.stringContaining('Có phải bạn không?'),
      }),
    );
    expect(insertValues).toEqual([
      expect.objectContaining({ participantId: PARTICIPANT_ID, userId: USER_ID }),
    ]);
    expect(updateValues).toEqual([]);

    const html = mailService.sendMail.mock.calls[0][0].html as string;
    const token = new URL(html.match(/href="([^"]+)"/)?.[1] ?? '').searchParams.get('token');
    expect(token).toBeTruthy();

    await service.confirm(token!);

    expect(updateValues).toEqual([{ rankingConsent: true }]);
  });

  it('does not grant consent when the email has no registered account', async () => {
    const participant = {
      participantId: PARTICIPANT_ID,
      participantName: 'Nguyễn An',
      tournamentName: 'Giải kiểm thử',
      rankingConsent: false,
      isMock: false,
      customResponses: { player1Email: EMAIL },
    };
    const selectRows = [[participant], []];
    const update = jest.fn();
    const db = {
      select: jest.fn(() => selectQuery(selectRows.shift() ?? [])),
      insert: jest.fn(),
      update,
    };
    const service = new ParticipantRankingConsentService(
      db as never,
      { get: jest.fn((key: string) => (key === 'auth.jwtAccessSecret' ? 'test-secret' : 'http://localhost:3101')) } as never,
      { sendMail: jest.fn().mockResolvedValue(true) } as never,
    );

