import { Module } from '@nestjs/common';
import { JwtModule } from '@nestjs/jwt';
import { PassportModule } from '@nestjs/passport';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { AuthService } from './auth.service';
import { AuthController } from './auth.controller';
import { AuthRepository } from './auth.repository';
import { JwtStrategy } from './strategies/jwt.strategy';
import { JwtRefreshStrategy } from './strategies/jwt-refresh.strategy';
import { GoogleStrategy } from './strategies/google.strategy';
import { BullModule } from '@nestjs/bullmq';
import { UsersModule } from '../users/users.module';
import { AccountSanctionModule } from '../../common/services/account-sanction.module';

@Module({
  imports: [
    PassportModule,
    UsersModule,
    AccountSanctionModule,
    BullModule.registerQueue({
      name: 'email-delivery',
    }),
    JwtModule.registerAsync({
      imports: [ConfigModule],
      inject: [ConfigService],
      useFactory: (configService: ConfigService) => {
        const expiresIn = configService.get<string>('auth.jwtAccessExpiresIn') || '15m';
        return {
          secret: configService.get<string>('auth.jwtAccessSecret'),
          // Safe cast: expiresIn string value is valid for JWT SignOptions
          signOptions: { expiresIn: expiresIn as unknown as never },
        };
      },
    }),
  ],
  controllers: [AuthController],
  providers: [AuthService, AuthRepository, JwtStrategy, JwtRefreshStrategy, GoogleStrategy],
  exports: [AuthService, JwtModule],
})
export class AuthModule {}

import {
  Injectable,
  UnauthorizedException,
  BadRequestException,
  ForbiddenException,
  ConflictException,
  InternalServerErrorException,
  Inject,
  Logger,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import * as bcrypt from 'bcrypt';
import * as crypto from 'crypto';
import * as jwt from 'jsonwebtoken';
import { OAuth2Client } from 'google-auth-library';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { eq, and, gt, sql } from 'drizzle-orm';
import { PG_CONNECTION } from '../../database/database.module';
import type { AppDb } from '../../database/db.types';
import * as schema from '../../database/schema';
import { AuthRepository } from './auth.repository';
import { UsersRepository } from '../users/users.repository';
import { RegisterDto } from './dto/register.dto';
import { LoginDto } from './dto/login.dto';
import { OAuthProfileDto } from './dto/oauth-profile.dto';
import { InvalidCredentialsException } from './exceptions/invalid-credentials.exception';
import { UserRole } from '../../common/constants/enums';
import { ERROR_MESSAGES } from '../../common/constants/error-messages';
import { AccountSanctionService } from '../../common/services/account-sanction.service';

@Injectable()
export class AuthService {
  private readonly googleClient: OAuth2Client;
  private readonly logger = new Logger(AuthService.name);

  constructor(
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    private readonly authRepository: AuthRepository,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
    private readonly usersRepository: UsersRepository,
    @InjectQueue('email-delivery') private readonly emailQueue: Queue,
    private readonly accountSanctionService: AccountSanctionService,
  ) {
    this.googleClient = new OAuth2Client(
      this.configService.get<string>('auth.googleClientId'),
    );
  }

  async register(registerDto: RegisterDto) {
    const email = registerDto.email.toLowerCase().trim();
    const existingUser = await this.authRepository.findUserByEmail(email);
    if (existingUser) {
      throw new ConflictException(ERROR_MESSAGES.EMAIL_ALREADY_EXISTS);
    }

    const hashedPassword = await bcrypt.hash(registerDto.password, 12);

    // Default role PLAYER (Tìm hoặc lấy role đầu tiên / fallback)
    let defaultRole = await this.authRepository.findRoleByName(UserRole.PLAYER);
    if (!defaultRole) {
      // Tìm không phân biệt hoa thường nếu có
      const [anyPlayerRole] = await this.db
        .select()
        .from(schema.roles)
        .where(sql`LOWER(${schema.roles.name}) = 'player'`)
        .limit(1);
      defaultRole = anyPlayerRole;
    }

    if (!defaultRole) {
      // Tự động tạo role PLAYER nếu DB chưa có
      const [createdRole] = await this.db
        .insert(schema.roles)
        .values({
          name: UserRole.PLAYER,
          slug: 'player',
          description: 'Vận động viên / Người chơi',
        })
        .onConflictDoNothing()
        .returning();
      defaultRole = createdRole || (await this.authRepository.findRoleByName(UserRole.PLAYER));
    }

    if (!defaultRole) {
      throw new InternalServerErrorException('Hệ thống chưa thiết lập vai trò người chơi (PLAYER).');
    }

    const newUser = await this.authRepository.createUserWithProfile(
      { email, passwordHash: hashedPassword },
      { fullName: registerDto.fullName, userId: '' }, // userId will be populated in repository
      defaultRole.id,
    );

    // Tạo userRanks mặc định (ELO 1000) cho tất cả category (bọc try/catch an toàn)
    try {
      await this.authRepository.createDefaultUserRanks(newUser.id);
    } catch (err) {
      this.logger.warn(`Không thể tạo userRank mặc định cho user ${newUser.id}: ${err.message}`);
    }

    delete (newUser as { passwordHash?: string | null }).passwordHash;
    return newUser;
  }

  async login(loginDto: LoginDto, userAgent?: string, ipAddress?: string) {
    const email = loginDto.email.toLowerCase().trim();
    const user = await this.authRepository.findUserByEmail(email);
    if (!user) {
      throw new InvalidCredentialsException();
    }

    if (!user.passwordHash) {
      throw new BadRequestException(
        'Tài khoản này được đăng ký qua Google. Vui lòng đăng nhập bằng Google.',
