              tx,
              tournament,
              divisionId,
            )
          ).toFixed(2),
          isWildcard: true,
          teamStatus,
        })
        .returning();

      await tx.insert(schema.tournamentRosters).values({
        participantId: participant.id,
        userId: userId,
        role: 'MAIN',
      });

      if (isDoubles && partnerId) {
        await tx.insert(schema.tournamentRosters).values({
          participantId: participant.id,
          userId: partnerId,
          role: 'MAIN',
        });
      }

      return participant;
    });
