import { BadRequestException, Inject, Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as jwt from 'jsonwebtoken';
import { and, eq, or, sql } from 'drizzle-orm';
import { PG_CONNECTION } from '../../database/database.module';
import type { AppDb } from '../../database/db.types';
import * as schema from '../../database/schema';
import { MailService } from '../../providers/mail/mail.service';

const TOKEN_PURPOSE = 'tournament-participant-ranking-consent';
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type ConsentToken = jwt.JwtPayload & {
  purpose: typeof TOKEN_PURPOSE;
  participantId: string;
  email: string;
};

type ParticipantConsentRow = {
  participantId: string;
  participantName: string;
  tournamentName: string;
  customResponses: unknown;
};

function normalizedEmail(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const email = value.trim().toLowerCase();
  return EMAIL_PATTERN.test(email) ? email : null;
}

function responsesOf(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function participantEmails(value: unknown): string[] {
  const responses = responsesOf(value);
  return [responses.player1Email, responses.player2Email]
    .map(normalizedEmail)
    .filter((email): email is string => email !== null);
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case '&': return '&amp;';
      case '<': return '&lt;';
      case '>': return '&gt;';
      case '"': return '&quot;';
      default: return '&#39;';
    }
  });
}

@Injectable()
export class ParticipantRankingConsentService {
  private readonly logger = new Logger(ParticipantRankingConsentService.name);

  constructor(
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    private readonly configService: ConfigService,
    private readonly mailService: MailService,
  ) {}

  async sendConfirmation(
    participantId: string,
    recipientEmail: string,
    participantName: string,
    tournamentName: string,
  ): Promise<boolean> {
    const email = normalizedEmail(recipientEmail);
    if (!email) return false;

    try {
      const token = jwt.sign(
        { purpose: TOKEN_PURPOSE, participantId, email },
        this.jwtSecret(),
        { expiresIn: '7d' },
      );
      const frontendUrl = (
        this.configService.get<string>('FRONTEND_URL') || 'http://localhost:3101'
      ).replace(/\/+$/, '');
      const confirmUrl = `${frontendUrl}/tournaments/ranking-consent?token=${encodeURIComponent(token)}`;
      const safeName = escapeHtml(participantName);
      const safeTournamentName = escapeHtml(tournamentName);
      const html = `
        <p>Xin chào ${safeName},</p>
        <p>Ban tổ chức đã ghi nhận bạn tham gia giải <strong>${safeTournamentName}</strong>.</p>
        <p><strong>Bạn đã tham gia giải này chưa? Có phải bạn không?</strong></p>
        <p>Chỉ khi bạn chủ động xác nhận, kết quả các trận đấu sau đó mới được tính vào bảng xếp hạng ELO. Trận đã diễn ra trước lúc xác nhận sẽ không được tính.</p>
        <p><a href="${confirmUrl}">Xác nhận tôi đã tham gia</a></p>
        <p>Nếu chưa có tài khoản, hãy đăng ký hoặc đăng nhập bằng email này trước khi xác nhận.</p>
      `;

      return await this.mailService.sendMail(
        email,
        `Xác nhận tham gia giải ${tournamentName}`,
        html,
      );
    } catch (error) {
      this.logger.warn('Không gửi được email xác nhận consent ELO.');
      return false;
    }
  }

  async handleAccountAccess(userId: string, emailValue: string): Promise<number> {
    const email = normalizedEmail(emailValue);
    if (!email) return 0;

    try {
      const rows = await this.db
        .select({
          participantId: schema.tournamentParticipants.id,
          participantName: schema.tournamentParticipants.teamName,
          tournamentName: schema.tournaments.name,
          customResponses: schema.tournamentParticipants.customResponses,
        })
        .from(schema.tournamentParticipants)
        .innerJoin(
          schema.tournaments,
          eq(schema.tournamentParticipants.tournamentId, schema.tournaments.id),
        )
        .where(
          and(
            eq(schema.tournamentParticipants.rankingConsent, false),
            eq(schema.tournamentParticipants.isMock, false),
            or(
              sql`lower(${schema.tournamentParticipants.customResponses}->>'player1Email') = ${email}`,
              sql`lower(${schema.tournamentParticipants.customResponses}->>'player2Email') = ${email}`,
            ),
          ),
        );

      let notifiedCount = 0;
      for (const row of rows) {
        if (!participantEmails(row.customResponses).includes(email)) continue;
        await this.linkRosterAccount(row, userId, email);
        if (
          await this.sendConfirmation(
            row.participantId,
            email,
            row.participantName,
            row.tournamentName,
          )
        ) {
          notifiedCount += 1;
        }
      }
      return notifiedCount;
    } catch (error) {
      this.logger.warn('Không xử lý được email participant consent sau khi đăng nhập.');
      return 0;
    }
  }

  async confirm(token: string): Promise<{ confirmed: true }> {
    let claims: ConsentToken;
    try {
      const decoded = jwt.verify(token, this.jwtSecret());
      if (
        typeof decoded === 'string' ||
        decoded.purpose !== TOKEN_PURPOSE ||
        typeof decoded.participantId !== 'string' ||
        !normalizedEmail(decoded.email)
      ) {
        throw new Error('Invalid consent token');
      }
      claims = decoded as ConsentToken;
    } catch {
      throw new BadRequestException('Liên kết xác nhận không hợp lệ hoặc đã hết hạn.');
    }

    const email = normalizedEmail(claims.email);
    if (!email) {
      throw new BadRequestException('Email xác nhận không hợp lệ.');
    }

    const [participant] = await this.db
      .select({
        participantId: schema.tournamentParticipants.id,
        rankingConsent: schema.tournamentParticipants.rankingConsent,
        isMock: schema.tournamentParticipants.isMock,
        customResponses: schema.tournamentParticipants.customResponses,
      })
      .from(schema.tournamentParticipants)
      .where(eq(schema.tournamentParticipants.id, claims.participantId))
      .limit(1);

    if (
      !participant ||
      participant.isMock ||
      !participantEmails(participant.customResponses).includes(email)
    ) {
      throw new BadRequestException('Không tìm thấy participant đăng ký bằng email này.');
    }

    const [user] = await this.db
      .select({ id: schema.users.id })
      .from(schema.users)
      .where(sql`lower(${schema.users.email}) = ${email}`)
      .limit(1);

    if (!user) {
      throw new BadRequestException(
        'Vui lòng đăng ký hoặc đăng nhập bằng email này trước khi xác nhận.',
      );
    }

    await this.linkRosterAccount(participant, user.id, email);
    if (!participant.rankingConsent) {
      await this.db
        .update(schema.tournamentParticipants)
        .set({ rankingConsent: true })
        .where(eq(schema.tournamentParticipants.id, claims.participantId));
    }

    return { confirmed: true };
  }

  private async linkRosterAccount(
    participant: ParticipantConsentRow,
    userId: string,
    email: string,
  ): Promise<void> {
    const responses = responsesOf(participant.customResponses);
    const role = normalizedEmail(responses.player2Email) === email ? 'MAIN' : 'MAIN';
    await this.db
      .insert(schema.tournamentRosters)
      .values({ participantId: participant.participantId, userId, role });
  }

  private jwtSecret(): string {
    const secret = this.configService.get<string>('auth.jwtAccessSecret');
    if (!secret) throw new Error('JWT access secret is not configured');
    return secret;
  }
}

