import * as bcrypt from 'bcrypt';
import { AuthService } from './auth.service';

function createAuthService(overrides: {
  authRepository?: Record<string, jest.Mock>;
  participantConsent?: { handleAccountAccess: jest.Mock };
}) {
  const authRepository = {
    findUserByEmail: jest.fn(),
    findRoleByName: jest.fn().mockResolvedValue({ id: 'role-player' }),
    createUserWithProfile: jest.fn(),
    createDefaultUserRanks: jest.fn().mockResolvedValue(undefined),
    findUserRoles: jest.fn().mockResolvedValue([]),
    ...overrides.authRepository,
  };
  const participantConsent = overrides.participantConsent ?? {
    handleAccountAccess: jest.fn().mockResolvedValue(0),
  };
  const service = new AuthService(
    {} as never,
    authRepository as never,
    {} as never,
    { get: jest.fn() } as never,
    {} as never,
    {} as never,
    { hasActiveAccessBan: jest.fn().mockResolvedValue(false) } as never,
    participantConsent as never,
  );

  return { service, authRepository, participantConsent };
}

describe('AuthService participant consent notifications', () => {
  it('checks for matching participant emails after registration', async () => {
    const newUser = {
      id: 'user-1',
      email: 'athlete@example.test',
      passwordHash: 'stored-hash',
      isMock: false,
    };
    const participantConsent = { handleAccountAccess: jest.fn().mockResolvedValue(0) };
    const { service, authRepository } = createAuthService({ participantConsent });
    authRepository.findUserByEmail.mockResolvedValue(null);
    authRepository.createUserWithProfile.mockResolvedValue(newUser);

    await service.register({
      email: newUser.email,
      password: 'password',
      fullName: 'VĐV kiểm thử',
    });

    expect(participantConsent.handleAccountAccess).toHaveBeenCalledWith(
      newUser.id,
      newUser.email,
      false,
    );
  });

  it('checks for matching participant emails after login', async () => {
    const user = {
      id: 'user-2',
      email: 'athlete@example.test',
      passwordHash: await bcrypt.hash('password', 4),
      isEmailVerified: true,
      isMock: false,
    };
    const participantConsent = { handleAccountAccess: jest.fn().mockResolvedValue(0) };
    const { service, authRepository } = createAuthService({ participantConsent });
    authRepository.findUserByEmail.mockResolvedValue(user);
    jest.spyOn(service as never, 'generateTokens').mockResolvedValue({ accessToken: 'token' } as never);

    await service.login({ email: user.email, password: 'password' });

    expect(participantConsent.handleAccountAccess).toHaveBeenCalledWith(
      user.id,
      user.email,
      false,
    );
  });
});

