import { BadRequestException, Inject, Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as jwt from 'jsonwebtoken';
import { and, eq, or, sql } from 'drizzle-orm';
import { PG_CONNECTION } from '../../database/database.module';
import type { AppDb } from '../../database/db.types';
import * as schema from '../../database/schema';
import { MailService } from '../../providers/mail/mail.service';

const TOKEN_PURPOSE = 'tournament-participant-ranking-consent';
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type ConsentToken = jwt.JwtPayload & {
  purpose: typeof TOKEN_PURPOSE;
  participantId: string;
  email: string;
};

type ParticipantConsentRow = {
  participantId: string;
  participantName: string;
  tournamentName: string;
  customResponses: unknown;
};

function normalizedEmail(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const email = value.trim().toLowerCase();
  return EMAIL_PATTERN.test(email) ? email : null;
}

function responsesOf(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function participantEmails(value: unknown): string[] {
  const responses = responsesOf(value);
  return [responses.player1Email, responses.player2Email]
    .map(normalizedEmail)
    .filter((email): email is string => email !== null);
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case '&': return '&amp;';
      case '<': return '&lt;';
      case '>': return '&gt;';
      case '"': return '&quot;';
      default: return '&#39;';
    }
  });
}

@Injectable()
export class ParticipantRankingConsentService {
