70:      divisionId: dto.divisionId,
71:      action: 'IMPORT_PARTICIPANTS',
72:    });
73:
74:    return {
75:      message: `Đã nạp thành công ${result.importedCount} VĐV / Đội vào giải đấu!`,
76:      importedCount: result.importedCount,
