78:        ? (result.unregisteredEmails?.length ?? 0)
79:        : 0,
80:    };
81:  }
82:  /**
83:   * Strict roster commit for the spreadsheet workflow: validated source, a
84:   * player-one email on every row and eligible-only capacity accounting.
85:   */
86:  async importRosterFromForm(
87:    tournamentId: string,
88:    userId: string,
