import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { ParticipantRankingConsentService } from '../../auth/participant-ranking-consent.service';
import { TournamentsRepository } from '../tournaments.repository';
import { TournamentAccessService } from './tournament-access.service';
import { NotificationsService } from '../../notifications/notifications.service';
import {
  buildParticipantRegistrationPendingNotification,
  buildParticipantRegistrationSuccessNotification,
} from '../../notifications/notification-builder';
import type { ImportParticipantsDto } from '../dto/import-participants.dto';
import type { RosterImportDto } from '../dto/roster-import.dto';

type RegistrationChangedBroadcaster = (
  tournamentId: string,
  payload: { divisionId?: string | null; action: string },
) => void;

@Injectable()
export class TournamentImportService {
  constructor(
    private readonly tournamentsRepository: TournamentsRepository,
    private readonly tournamentAccessService: TournamentAccessService,
    private readonly notificationsService: NotificationsService,
    private readonly participantRankingConsentService: ParticipantRankingConsentService,
  ) {}
  /**
   * Legacy import used by released clients; unregistered contacts still receive
   * the same explicit participant-consent confirmation as spreadsheet imports.
   */
  async importParticipantsFromForm(
    tournamentId: string,
    userId: string,
    systemRoles: string[],
    dto: ImportParticipantsDto,
    broadcastRegistrationChanged: RegistrationChangedBroadcaster,
  ) {
    const tournament = await this.assertImportable(
      tournamentId,
      userId,
      systemRoles,
    );

    const result = await this.tournamentsRepository.importParticipants(
      tournamentId,
      userId,
      dto.participants,
      dto.divisionId,
    );

    await this.notifyLinkedAccounts(
      tournamentId,
      tournament.name,
      dto.notifyLinkedAccounts === true,
      result.linkedAccountNotifications,
    );

    const emailsSent = await this.sendConsentConfirmations(
      result.participants ?? [],
      tournament.name,
    );

    broadcastRegistrationChanged(tournamentId, {
      divisionId: dto.divisionId,
      action: 'IMPORT_PARTICIPANTS',
    });

    return {
      message: `Đã nạp thành công ${result.importedCount} VĐV / Đội vào giải đấu!`,
      importedCount: result.importedCount,
      emailsSent,
    };
  }
  /**
   * Strict roster commit for the spreadsheet workflow: validated source,
   * optional contact details and eligible-only capacity accounting.
   */
  async importRosterFromForm(
    tournamentId: string,
    userId: string,
    systemRoles: string[],
    dto: RosterImportDto,
    broadcastRegistrationChanged: RegistrationChangedBroadcaster,
  ) {
    const tournament = await this.assertImportable(
      tournamentId,
      userId,
      systemRoles,
    );

    const result = await this.tournamentsRepository.importRosterRows(
      tournamentId,
      userId,
      dto.participants,
      dto.divisionId,
    );

    await this.notifyLinkedAccounts(
      tournamentId,
      tournament.name,
      dto.notifyLinkedAccounts === true,
      result.linkedAccountNotifications,
    );

    const emailsSent = await this.sendConsentConfirmations(
      result.participants ?? [],
      tournament.name,
    );

    broadcastRegistrationChanged(tournamentId, {
      divisionId: dto.divisionId,
      action: 'IMPORT_PARTICIPANTS',
    });

    return {
      message: `Đã thêm ${result.importedCount} VĐV / Đội vào giải đấu!`,
      importedCount: result.importedCount,
      emailsSent,
    };
  }
  private async assertImportable(
    tournamentId: string,
    userId: string,
    systemRoles: string[],
  ) {
    const tournament = await this.tournamentsRepository.findById(tournamentId);
    if (!tournament) throw new NotFoundException('Giải đấu không tồn tại');

    const isAuthorized = await this.tournamentAccessService.isManager(
      tournament,
      userId,
      systemRoles,
    );
    if (!isAuthorized) {
      throw new ForbiddenException('Bạn không có quyền nhập danh sách VĐV');
    }

    if (tournament.status === 'COMPLETED') {
      throw new BadRequestException('Giải đấu đã kết thúc');
    }
    if (
      tournament.status === 'REGISTRATION_CLOSED' ||
      tournament.isRegistrationLocked
    ) {
        'Đăng ký đã được khóa. Không thể nhập thêm VĐV.',
    }

    return tournament;
  }
  private async notifyLinkedAccounts(
    tournamentId: string,
    tournamentName: string,
    requested: boolean,
    recipients:
      | Array<{
          userId: string;
          status: 'COMPLETE' | 'PENDING_APPROVAL';
          divisionId: string | null;
        }>
      | undefined,
  ): Promise<void> {
    if (!requested || !recipients?.length) return;
    for (const recipient of recipients) {
      try {
        const notification =
          recipient.status === 'COMPLETE'
            ? buildParticipantRegistrationSuccessNotification({
                tournamentId,
                tournamentName,
                receiverId: recipient.userId,
                divisionId: recipient.divisionId,
              })
            : buildParticipantRegistrationPendingNotification({
                tournamentId,
                tournamentName,
                receiverId: recipient.userId,
                divisionId: recipient.divisionId,
              });
        await this.notificationsService.sendNotification(notification);
      } catch {
        // A notification failure must not roll back a successful import.
      }
    }
  }
  private async sendConsentConfirmations(
    participants: Array<{
      id: string;
      teamName: string;
      customResponses: unknown;
    }>,
    tournamentName: string,
  ): Promise<number> {
    let emailsSent = 0;
    for (const participant of participants) {
      const responses =
        participant.customResponses &&
        typeof participant.customResponses === 'object' &&
        !Array.isArray(participant.customResponses)
          ? (participant.customResponses as Record<string, unknown>)
          : {};
      const sentTo = new Set<string>();
      for (const player of [1, 2] as const) {
        const email = responses[`player${player}Email`];
        if (typeof email !== 'string' || !email.trim()) continue;
        const normalizedEmail = email.trim().toLowerCase();
        if (sentTo.has(normalizedEmail)) continue;
        sentTo.add(normalizedEmail);
        const name = responses[`player${player}Name`];
        const sent = await this.participantRankingConsentService.sendConfirmation(
          participant.id,
          email,
          typeof name === 'string' && name.trim() ? name.trim() : participant.teamName,
          tournamentName,
        );
        if (sent) emailsSent += 1;
      }
    }
    return emailsSent;
  }
}

