import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import {
  IsArray,
  IsBoolean,
  IsNumber,
  IsOptional,
  IsString,
  ValidateNested,
} from 'class-validator';

/**
 * Legacy import payload for `POST /tournaments/:id/import-participants`.
 *
 * Kept byte-compatible with the pre-roster endpoint: emails are optional plain
 * strings, provenance is not declared and `sendInvitationEmail` still exists,
 * so already released web/mobile clients keep working unchanged.
 */
export class ParticipantImportItemDto {
  @ApiProperty({ description: 'Tên đội / cặp đấu hoặc tên VĐV' })
  @IsString()
  teamName: string;

  @ApiProperty({ description: 'Họ tên VĐV 1' })
  @IsString()
  player1Name: string;

  @ApiPropertyOptional({ description: 'Email VĐV 1' })
  @IsOptional()
  @IsString()
  player1Email?: string;

  @ApiPropertyOptional({ description: 'SĐT VĐV 1' })
  @IsOptional()
  @IsString()
  player1Phone?: string;

  @ApiPropertyOptional({ description: 'Họ tên VĐV 2 (nếu giải đôi)' })
  @IsOptional()
  @IsString()
  player2Name?: string;

  @ApiPropertyOptional({ description: 'Email VĐV 2' })
  @IsOptional()
  @IsString()
  player2Email?: string;

  @ApiPropertyOptional({ description: 'SĐT VĐV 2' })
  @IsOptional()
  @IsString()
  player2Phone?: string;

  @ApiPropertyOptional({ description: 'Điểm trình / ELO khởi tạo' })
  @IsOptional()
  @IsNumber()
  elo?: number;

  @ApiPropertyOptional({ description: 'Đã thanh toán lệ phí hay chưa' })
  @IsOptional()
  @IsBoolean()
  isPaid?: boolean;

  @ApiPropertyOptional({ description: 'Tự động duyệt hồ sơ (APPROVED)' })
  @IsOptional()
  @IsBoolean()
  autoApprove?: boolean;

  @ApiPropertyOptional({ description: 'Ghi chú / câu trả lời custom form' })
  @IsOptional()
  customResponses?: Record<string, unknown>;
}

