export function RegistrationTab({
…
}: RegistrationTabProps) {
…
  return (
    <div className="w-full space-y-6 animate-in fade-in duration-200">
…
        {isWildcardModalOpen && (
          <Modal open={isWildcardModalOpen} onOpenChange={setIsWildcardModalOpen}>
            <ModalContent className="max-w-md bg-white p-0">
…
              <div className="p-5 space-y-4">
…
                {divisions.length > 1 && (
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-600 uppercase tracking-wider">
                      {registrationTranslate('contentSelectionLabel')}
                    </label>
                    <select
                      value={selectedDivisionId}
                      onChange={(e) => {
                        setSelectedDivisionId(e.target.value);
                        setWildcardPartnerEmailOrPhone('');
                      }}
                      className="w-full h-10 px-3 py-2 text-xs font-medium bg-slate-50 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                      {divisions.map((d) => (
                        <option key={d.id} value={d.id}>
                          {d.name} ({d._count?.participants ?? 0} VĐV)
                        </option>
                      ))}
                    </select>
                  </div>
                )}

                {(() => {
                  const currentDivision = divisions.find((d) => d.id === selectedDivisionId);
                  const isDoubles = currentDivision?.matchType === 'DOUBLES' || currentDivision?.matchType === 'MIXED_DOUBLES';
                  return (
                    <div className="space-y-3">
                      <Input
                        label={registrationTranslate('playerEmailPhoneLabel')}
                        placeholder={registrationTranslate('playerEmailPhonePlaceholder')}
                        value={wildcardEmailOrPhone}
                        onChange={(e) => setWildcardEmailOrPhone(e.target.value)}
                        className="bg-white text-xs h-10"
                        disabled={isAssigningWildcard}
                      />

                      {isDoubles && (
                        <Input
                          label={registrationTranslate('teammateLabel')}
                          placeholder={registrationTranslate('teammatePlaceholder')}
                          value={wildcardPartnerEmailOrPhone}
                          onChange={(e) => setWildcardPartnerEmailOrPhone(e.target.value)}
                          className="bg-white text-xs h-10"
                          disabled={isAssigningWildcard}
                        />
                      )}

                      <Input
                        label={registrationTranslate('wildcardTeamNameLabel')}
                        placeholder={registrationTranslate('wildcardTeamNamePlaceholder')}
                        value={wildcardTeamName}
                        onChange={(e) => setWildcardTeamName(e.target.value)}
                        className="bg-white text-xs h-10"
                        disabled={isAssigningWildcard}
                      />
                    </div>
                  );
                })()}
              </div>

              <div className="flex items-center justify-end gap-2 border-t border-slate-200 px-5 py-3.5 bg-slate-50">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setIsWildcardModalOpen(false)}
                  disabled={isAssigningWildcard}
                  className="border-slate-200 text-slate-700 hover:bg-white text-xs font-bold"
                >
                  {registrationTranslate('close')}
                </Button>
                <Button
                  type="button"
                  size="sm"
                  onClick={async () => {
                    try {
                      await handleAssignWildcard();
                      setIsWildcardModalOpen(false);
                    } catch {
                      // Keep modal open if error
                    }
                  }}
                  disabled={isAssigningWildcard || !wildcardEmailOrPhone.trim() || !wildcardTeamName.trim()}
                  className="bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center gap-1.5 shadow-sm"
                >
                  {isAssigningWildcard ? (
                    <>
                      <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      {registrationTranslate('assigningWildcard')}
                    </>
                  ) : (
                    <>
                      <CheckCircle className="w-3.5 h-3.5" />
                      {registrationTranslate('assignWildcard')}
                    </>
                  )}
                </Button>
              </div>
            </ModalContent>
          </Modal>
        )}
        <PairingParticipantsModal
          open={isPairingModalOpen}
          onOpenChange={setIsPairingModalOpen}
          participants={pairingParticipants}
          divisions={divisions}
          isLoading={isLoadingPairingParticipants}
          isPairing={isPairing}
          divisionName={selectedMockDivision?.name ?? ''}
          onPair={handleOrganizerPairing}
          onGenerateRandomPairs={handleGenerateRandomPairs}
        />

      </div>
  );
}

/** A wildcard row is a request for the organizer to review, never a granted slot. */
export type ImportEntryType = "REGULAR" | "WILD_CARD_REQUEST";

export interface RosterImportItem {
  teamName?: string;
  player1Name: string;
  player1Email: string;
  player1Phone?: string;
  player2Name?: string;
  player2Email?: string;
  player2Phone?: string;
  elo?: number;
  isPaid?: boolean;
  autoApprove?: boolean;
  entryType?: ImportEntryType;
  source: ImportSource;
  customResponses?: Record<string, unknown>;
}

export type RosterRowStatus =
  | "FOUND"
  | "NOT_FOUND"
  | "INVALID_EMAIL"
  | "MISSING_EMAIL"
  | "MISSING_NAME"
  | "DUPLICATE_IN_FILE"
  | "DUPLICATE_IN_TOURNAMENT"
  | "PLAYER2_REQUIRED"
  | "PLAYER2_NOT_ALLOWED"
  | "DIVISION_UNKNOWN";

export interface RosterPreviewRow {
  rowIndex: number;
  player1Email: string;
  player2Email: string | null;
  status: RosterRowStatus[];
  isEligible: boolean;
  capacityDelta: number;
}

export interface RosterImportPreview {
  divisionMatched: boolean;
  rows: RosterPreviewRow[];
  requestedTeamSlots: number;
  capacityRemaining: number | null;
}

export const tournamentsApi = {
  getFeesConfig: () =>
    api.get<ApiResponse<TournamentFeesConfig>>("/tournaments/fees"),
  getTournaments: (params?: Record<string, unknown>) =>
    api.get<PaginatedTournaments>("/tournaments", { params }),
  getPublicTournaments: (params?: Record<string, unknown>) =>
    api.get<PaginatedTournaments>("/tournaments/public", { params }),
  getMyTournaments: () => api.get<ApiResponse<Tournament[]>>("/tournaments/my"),
  getMyManagementTournaments: (params?: {
    cursor?: string;
    limit?: number;
    offset?: number;
    status?: "COMPLETED";
  }) =>
    api.get<ApiResponse<OrganizerTournamentListItem[]>>(
      "/tournaments/my/management",
      { params },
    ),
  getMyWorkspace: (params?: { includeRefereeMatches?: boolean }) =>
    api.get<ApiResponse<TournamentWorkspace>>("/tournaments/workspace/me", {
      params,
    }),
  getTournamentById: (id: string, params?: Record<string, unknown>) =>
    api.get<ApiResponse<Tournament>>(`/tournaments/${id}`, { params }),
  getTournamentVenues: (id: string) =>
    api.get<ApiResponse<TournamentVenueWithCourts[]>>(
      `/tournaments/${id}/venues`,
    ),
  createTournamentVenue: (
    id: string,
    data: {
      name: string;
      locationAddress: string;
      venueId?: string;
      isDefault?: boolean;
      initialCourtCount?: number;
      courtPrefix?: string;
    },
  ) =>
    api.post<ApiResponse<TournamentVenueWithCourts>>(
      `/tournaments/${id}/venues`,
      data,
    ),
  updateTournamentVenue: (
    id: string,
    venueId: string,
    data: { name?: string; locationAddress?: string },
  ) =>
    api.patch<ApiResponse<TournamentVenueWithCourts>>(
      `/tournaments/${id}/venues/${venueId}`,
      data,
    ),
  setDefaultTournamentVenue: (id: string, venueId: string) =>
    api.patch<ApiResponse<{ success: boolean; defaultVenueId: string }>>(
      `/tournaments/${id}/venues/${venueId}/default`,
    ),
  deleteTournamentVenue: (id: string, venueId: string) =>
    api.delete<
      ApiResponse<{
        success: boolean;
        remainingVenueIds: string[];
        defaultVenueId: string | null;
      }>
    >(`/tournaments/${id}/venues/${venueId}`),
  addVenueCourtDirect: (
    id: string,
    venueId: string,
    data: { courtName: string; status?: "AVAILABLE" | "MAINTENANCE" },
  ) =>
    api.post<ApiResponse<TournamentCourt>>(
      `/tournaments/${id}/venues/${venueId}/courts`,
      data,
    ),
  addVenueCourtsBatchDirect: (
    id: string,
    venueId: string,
    data: { courtCount: number; namePrefix?: string },
  ) =>
    api.post<ApiResponse<TournamentCourt[]>>(
      `/tournaments/${id}/venues/${venueId}/courts/batch`,
      data,
    ),
  removeVenueCourtDirect: (id: string, venueId: string, courtId: string) =>
    api.delete<ApiResponse<TournamentCourt>>(
      `/tournaments/${id}/venues/${venueId}/courts/${courtId}`,
    ),
