import * as schema from '../../../database/schema';
import type { AppTx } from '../../../database/db.types';

type ParticipantInsert = Omit<
  typeof schema.tournamentParticipants.$inferInsert,
  'rankingConsent' | 'isMock'
>;

export async function createTournamentParticipant(
  tx: AppTx,
  values: ParticipantInsert,
  rosterUserIds: readonly (string | null | undefined)[] = [],
) {
  const [participant] = await tx
    .insert(schema.tournamentParticipants)
    .values({ ...values, rankingConsent: false, isMock: false })
    .returning();

  for (const userId of new Set(rosterUserIds.filter((id): id is string => Boolean(id)))) {
    await tx.insert(schema.tournamentRosters).values({
      participantId: participant.id,
      userId,
      role: 'MAIN',
    });
  }

  return participant;
}

export class ImportParticipantsDto {
  @ApiPropertyOptional({ description: 'ID của division / nội dung thi đấu' })
  @IsOptional()
  @IsString()
  divisionId?: string;

  @ApiProperty({
    description: 'Danh sách VĐV / Đội cần nhập',
    type: [ParticipantImportItemDto],
  })
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => ParticipantImportItemDto)
  participants: ParticipantImportItemDto[];

  @ApiPropertyOptional({
    description: 'Tự động gửi email thư mời kích hoạt tài khoản',
  })
  @IsOptional()
  @IsBoolean()
  sendInvitationEmail?: boolean;

  @ApiPropertyOptional({
    description: 'Gửi thông báo trong SportO cho các VĐV đã có tài khoản',
  })
  @IsOptional()
  @IsBoolean()
  notifyLinkedAccounts?: boolean;
}

