import { BadRequestException } from '@nestjs/common';
import { TournamentFootballRosterService } from './tournament-football-roster.service';

describe('TournamentFootballRosterService.assignReservedSlot', () => {
  const tournament = {
    id: 'tournament-1',
    name: 'Giải thử nghiệm',
    status: 'REGISTRATION_OPEN',
  } as never;

  it('creates an unlinked contact participant and sends the plain confirmation', async () => {
    const participant = { id: 'participant-1', tournamentDivisionId: null };
    const repository = {
      findById: jest.fn().mockResolvedValue(tournament),
      findUserByEmailOrPhone: jest.fn().mockResolvedValue(null),
      assignReservedSlot: jest.fn().mockResolvedValue(participant),
    };
    const access = { isManager: jest.fn().mockResolvedValue(true) };
    const consent = { sendConfirmation: jest.fn().mockResolvedValue(true) };
    const service = new TournamentFootballRosterService(
      repository as never,
      access as never,
      {} as never,
      {} as never,
      consent as never,
    );

    await service.assignReservedSlot(
      'tournament-1',
      { name: 'Nguyễn An', email: 'an@example.test', phone: '0900000000' },
      'organizer-1',
    );

    expect(repository.assignReservedSlot).toHaveBeenCalledWith(
      'tournament-1',
      'organizer-1',
      expect.objectContaining({
        name: 'Nguyễn An',
        email: 'an@example.test',
        phone: '0900000000',
        participantUserId: null,
      }),
    );
    expect(consent.sendConfirmation).toHaveBeenCalledWith(
      'participant-1',
      'an@example.test',
      'Nguyễn An',
      'Giải thử nghiệm',
    );
  });

  it('requires at least one contact address but does not require Gmail specifically', async () => {
    const repository = {
      findById: jest.fn().mockResolvedValue(tournament),
      findUserByEmailOrPhone: jest.fn(),
      assignReservedSlot: jest.fn(),
    };
    const service = new TournamentFootballRosterService(
      repository as never,
      { isManager: jest.fn().mockResolvedValue(true) } as never,
      {} as never,
      {} as never,
      { sendConfirmation: jest.fn() } as never,
    );

    await expect(
      service.assignReservedSlot(
        'tournament-1',
        { name: 'Nguyễn An' },
        'organizer-1',
      ),
    ).rejects.toBeInstanceOf(BadRequestException);
    expect(repository.assignReservedSlot).not.toHaveBeenCalled();
  });
});

