  it('sends a plain consent confirmation on the legacy import path without an invite flag', async () => {
    repositoryMock.importParticipants.mockResolvedValue({
      importedCount: 1,
      participants: [
        {
          id: 'participant-legacy',
          teamName: 'Khách',
          customResponses: {
            player1Name: 'Khách',
            player1Email: 'guest@example.test',
          },
