      ],
      linkedAccountNotifications: [],
    });

    const dto = Object.assign(new ImportParticipantsDto(), {
      participants: [{ teamName: 'Khách', player1Name: 'Khách' }],
    });
    const result = await buildImporter().importParticipantsFromForm(
      'tournament-1',
      'organizer-1',
      [],
      dto,
      jest.fn(),
    );

    expect(consentMock.sendConfirmation).toHaveBeenCalledWith(
      'participant-legacy',
      'guest@example.test',
      'Khách',
      openTournament.name,
    );
    expect(result.emailsSent).toBe(1);
  });

  it('sends the same confirmation on the strict Excel import path', async () => {
    repositoryMock.importRosterRows.mockResolvedValue({
      importedCount: 1,
      linkedAccountNotifications: [],
      participants: [
        {
          id: 'participant-excel',
          teamName: 'VĐV Excel',
          customResponses: {
            player1Name: 'VĐV Excel',
            player1Email: 'excel@example.test',
          },
        },
      ],
    });

    const dto = Object.assign(new RosterImportDto(), {
      participants: [
        {
          teamName: 'VĐV Excel',
          player1Name: 'VĐV Excel',
          player1Email: 'excel@example.test',
          source: 'EXCEL',
        },
      ],
    });
    const broadcast = jest.fn();

    const result = await buildImporter().importRosterFromForm(
      'tournament-1',
      'organizer-1',
      [],
      dto,
      broadcast,
    );

    expect(consentMock.sendConfirmation).toHaveBeenCalledWith(
      'participant-excel',
      'excel@example.test',
      'VĐV Excel',
      openTournament.name,
    );
    expect(result.importedCount).toBe(1);
    expect(broadcast).toHaveBeenCalledWith('tournament-1', {
      divisionId: undefined,
      action: 'IMPORT_PARTICIPANTS',
    });
  });

