import { BadRequestException } from '@nestjs/common';
import { TournamentLiteService } from './tournament-lite.service';

describe('TournamentLiteService ranking consent', () => {
  const rankedLiteTournament = {
    id: 'tournament-1',
    name: 'Giải Lite',
    inviteCode: 'invite-1',
    tournamentConfig: { isLite: true },
    isRanked: true,
    communityId: null,
    status: 'REGISTRATION_OPEN',
    matchType: 'SINGLES',
    maxParticipants: null,
  } as never;

  const createService = (repository: Record<string, jest.Mock>, consent = { sendConfirmation: jest.fn() }) =>
    new TournamentLiteService(
      repository as never,
      { isManager: jest.fn().mockResolvedValue(true) } as never,
      {} as never,
      {} as never,
      {} as never,
      {} as never,
      { get: jest.fn() } as never,
      consent as never,
    );

  it('requires explicit consent for a ranked Lite self-registration', async () => {
    const repository = {
      findByInviteCode: jest.fn().mockResolvedValue(rankedLiteTournament),
      getDivisionsByTournament: jest.fn().mockResolvedValue([{ id: 'division-1' }]),
      findParticipantByTournamentAndUser: jest.fn().mockResolvedValue(null),
      countLiteActiveRosterUsers: jest.fn().mockResolvedValue(0),
      findUserProfile: jest.fn().mockResolvedValue({ fullName: 'Nguyễn An' }),
      registerParticipant: jest.fn(),
    };
    const service = createService(repository);

    await expect(
      service.joinLite('invite-1', 'user-1', undefined, false),
    ).rejects.toBeInstanceOf(BadRequestException);
    expect(repository.registerParticipant).not.toHaveBeenCalled();
  });

  it('keeps organizer-added Lite members unconsented and sends the confirmation email', async () => {
    const repository = {
      findById: jest.fn().mockResolvedValue({ ...rankedLiteTournament, communityId: 'club-1' }),
      getDivisionsByTournament: jest.fn().mockResolvedValue([]),
      findCommunityMember: jest.fn().mockResolvedValue({ status: 'JOINED' }),
      findUserProfile: jest.fn().mockResolvedValue({ fullName: 'Nguyễn An' }),
      findUserBasicById: jest.fn().mockResolvedValue({ email: 'an@example.test' }),
    };
    const consent = { sendConfirmation: jest.fn().mockResolvedValue(true) };
    const registerParticipant = jest.fn().mockResolvedValue({
      participant: { id: 'participant-1' },
    });
    const service = createService(repository, consent);

    await service.addLiteClubMember(
      'tournament-1',
      'athlete-1',
      'organizer-1',
      registerParticipant,
    );

    expect(registerParticipant).toHaveBeenCalledWith(
      'tournament-1',
      'athlete-1',
      expect.objectContaining({
        rankingConsent: false,
        customResponses: expect.objectContaining({ player1Email: 'an@example.test' }),
      }),
      undefined,
      'organizer-1',
    );
    expect(consent.sendConfirmation).toHaveBeenCalledWith(
      'participant-1',
      'an@example.test',
      'Nguyễn An',
      'Giải Lite',
    );
  });
});

