    expect(repository.assignReservedSlot).toHaveBeenCalledWith(
      'tournament-1',
      'organizer-1',
      expect.objectContaining({ player1Phone: '0900000000' }),
    );
    expect(consent.sendConfirmation).not.toHaveBeenCalled();
  });

